 private Student student(String id,String name,String email,String branch,double cg,double t,double i,String skills,int p,int in,double c,double a,double comm,double res,double iv,double read,String status){Student s=new Student();s.setStudentId(id);s.setName(name);s.setEmail(email);s.setPassword(email.equals("student@campus.local")?"demo123":"demo123");s.setBranch(branch);s.setCgpa(cg);s.setTenthPercentage(t);s.setIntermediatePercentage(i);s.setSkills(skills);s.setProjects(p);s.setInternships(in);s.setBacklogs(0);s.setEducationGap(0);s.setCodingScore(c);s.setAptitudeScore(a);s.setCommunicationScore(comm);s.setResumeScore(res);s.setInterviewScore(iv);s.setReadinessScore(read);s.setPlacementStatus(status);return s;}
 private Company company(String n,String r,double cg,double t,double i,int b,int g,String br,String sk,String desc,String loc,String launch,String deadline,String drive){Company c=new Company();c.setName(n);c.setRole(r);c.setMinCgpa(cg);c.setMinTenth(t);c.setMinIntermediate(i);c.setMaxBacklogs(b);c.setMaxEducationGap(g);c.setBranches(br);c.setRequiredSkills(sk);c.setDescription(desc);c.setLocation(loc);c.setLaunchDate(launch);c.setApplicationDeadline(deadline);c.setDriveDate(drive);c.setSalary(salaryFor(n));return c;}
 private String salaryFor(String n){return switch(n){case "TechNova" -> "₹8 LPA"; case "DataSphere" -> "₹7.5 LPA"; case "CloudWorks" -> "₹9 LPA"; case "FinEdge" -> "₹8.5 LPA"; case "InnoSoft" -> "₹6.5 LPA"; default -> "₹6 LPA";};}
 private PlacementDrive drive(String c,String r,String d,String b,String p){PlacementDrive x=new PlacementDrive();x.setCompanyName(c);x.setRole(r);x.setDriveDate(d);x.setEligibleBranches(b);x.setProcess(p);return x;}
 private Application app(String s,String c,String st,String status,String date){Application a=new Application();a.setStudentId(s);a.setCompanyName(c);a.setStage(st);a.setStatus(status);a.setAppliedAt(date);return a;}
 private LearningResource res(String skill,String title,String type,String level,String url,String desc,int hours){LearningResource r=new LearningResource();r.setSkill(skill);r.setTitle(title);r.setType(type);r.setLevel(level);r.setUrl(url);r.setDescription(desc);r.setEstimatedHours(hours);return r;}
