 private void live(LiveOpportunityRepository r,String c,String role,String loc,String posted,String deadline,String source,String sourceUrl,String apply,String skills,String batch,String eligibility,String desc,boolean verified){if(r.findByCompanyIgnoreCaseAndRoleIgnoreCaseAndPostedDate(c,role,posted).isPresent())return;LiveOpportunity o=new LiveOpportunity();o.setCompany(c);o.setRole(role);o.setLocation(loc);o.setPostedDate(posted);o.setDeadline(deadline);o.setSource(source);o.setSourceUrl(sourceUrl);o.setApplyUrl(apply);o.setRequiredSkills(skills);o.setBatch(batch);o.setEligibility(eligibility);o.setDescription(desc);o.setVerified(verified);r.save(o);}

